package com.kuaixietech.refunds;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.kuaixietech.payments.PaymentModels.Merchant;
import com.kuaixietech.service.finance.impl.AtomicMoneyService;
import java.math.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.refunds.RefundModels.*;
class RefundSafetyTest {
 static final String PAYMENT="a".repeat(32),ID="b".repeat(32),REQUEST="123e4567-e89b-42d3-a456-426614174000";
 final JdbcTemplate db=mock(JdbcTemplate.class);final AtomicMoneyService money=mock(AtomicMoneyService.class);final List<String> writes=new ArrayList<>();
 Map<String,Object> payment=new HashMap<>(),refund=null,byRequest=null,verified=new HashMap<>();boolean alreadyRequested=false;
 RefundTransactions service()throws Exception{var merchant=new Merchant("merchant","WeChat","wechat_native_v3","wechat","web",List.of("CNY"),"WECHAT_MAIN",0,300,true,1,Map.of("_identity_MERCHANT_ID","m"));payment.putAll(Map.of("id",PAYMENT,"user_id","buyer","merchant_id","merchant","status","paid","base_currency","CNY","base_minor",new BigDecimal("10000"),"payment_currency","CNY","payment_minor",new BigDecimal("10000"),"payment_minor_digits",2,"provider_transaction_id","tx"));payment.put("merchant_snapshot",new ObjectMapper().writeValueAsString(merchant));verified.putAll(Map.of("merchant_id","merchant","provider_transaction_id","tx","payment_currency","CNY","payment_minor",new BigDecimal("10000"),"base_minor",new BigDecimal("10000"),"payment_minor_digits",2));
  when(db.queryForList(anyString(),any(Object[].class))).thenAnswer(c->{String sql=c.getArgument(0);if(sql.startsWith("SELECT * FROM t_currency_payments"))return payment.isEmpty()?List.of():List.of(payment);if(sql.startsWith("SELECT * FROM t_payment_refunds WHERE user_id"))return byRequest==null?List.of():List.of(byRequest);if(sql.startsWith("SELECT id FROM t_payment_refunds"))return alreadyRequested?List.of(Map.of("id",ID)):List.of();if(sql.startsWith("SELECT merchant_id,provider_transaction_id"))return verified==null?List.of():List.of(verified);if(sql.startsWith("SELECT * FROM t_payment_refunds WHERE id"))return refund==null?List.of():List.of(refund);return List.of();});
  when(db.update(anyString(),any(Object[].class))).thenAnswer(c->{String sql=c.getArgument(0);Object[] a=(Object[])c.getRawArguments()[1];writes.add(sql);if(sql.startsWith("INSERT INTO t_payment_refunds(")){refund=new HashMap<>(payment);refund.put("id",a[0]);refund.put("payment_id",a[1]);refund.put("request_id",a[3]);refund.put("status","requested");refund.put("reason",a[8]);refund.put("wallet_released",false);}if(sql.startsWith("UPDATE t_payment_refunds SET status=?")){refund.put("status",a[0]);if(sql.contains("review_note")){refund.put("review_note",a[1]);refund.put("reviewed_by",a[2]);}if(sql.contains("provider_refund_id"))refund.put("provider_refund_id",a[1]);}if(sql.startsWith("UPDATE t_payment_refunds SET status='cancelled'"))refund.put("status","cancelled");if(sql.startsWith("UPDATE t_payment_refunds SET status='dispatching'"))refund.put("status","dispatching");if(sql.startsWith("UPDATE t_payment_refunds SET wallet_released=1"))refund.put("wallet_released",true);return 1;});
  when(money.lockBalance("buyer")).thenReturn(new BigDecimal("100.00"));when(money.addBalance(any(),any(),any(),any(),any())).thenReturn(new BigDecimal("100.00"));return new RefundTransactions(new RefundStore(db,new ObjectMapper()),money);
 }
 Create input(){return new Create(PAYMENT,REQUEST,"Unused recharge");}
 void existing(String status){refund=new HashMap<>(payment);refund.put("id",ID);refund.put("payment_id",PAYMENT);refund.put("status",status);refund.put("reason","Unused recharge");refund.put("wallet_released",false);}
 Receipt receipt(String status){return new Receipt(ID,PAYMENT,"tx","provider-refund","CNY",new BigInteger("10000"),new BigInteger("10000"),status);}
 void code(String expected,Runnable work){var e=assertThrows(ResponseStatusException.class,work::run);assertEquals(expected,e.getReason());}
 @Test void sourceMustBePaidAndVerifiedBeforeAnyWalletMovement()throws Exception{var s=service();verified=null;code("REFUND_VERIFIED_SOURCE_REQUIRED",()->s.reserve("buyer",input()));verifyNoInteractions(money);assertTrue(writes.isEmpty());}
 @Test void nonCnyRechargeCannotEnterThisRefundFlow()throws Exception{var s=service();payment.put("payment_currency","USD");code("REFUND_SOURCE_NOT_ELIGIBLE",()->s.reserve("buyer",input()));verifyNoInteractions(money);}
 @Test void eachOriginalAmountMustMatchItsVerifiedReceipt()throws Exception{var s=service();payment.put("payment_minor",new BigDecimal("9999"));code("REFUND_VERIFIED_SOURCE_REQUIRED",()->s.reserve("buyer",input()));verifyNoInteractions(money);}
 @Test void sameOriginalPaymentCannotBeRefundedTwice()throws Exception{var s=service();alreadyRequested=true;code("REFUND_ALREADY_REQUESTED",()->s.reserve("buyer",input()));verifyNoInteractions(money);}
 @Test void insufficientWalletCannotCreateNegativeAvailableBalance()throws Exception{var s=service();when(money.lockBalance("buyer")).thenReturn(new BigDecimal("99.99"));code("REFUND_INSUFFICIENT_AVAILABLE_BALANCE",()->s.reserve("buyer",input()));verify(money,never()).addBalance(any(),any(),any(),any(),any());assertTrue(writes.isEmpty());}
 @Test void requestReservesExactlyTheOriginalCreditAndDoesNotAlterPaymentStatus()throws Exception{var s=service();var result=s.reserve("buyer",input());assertEquals("requested",result.get("status"));verify(money).addBalance(eq("buyer"),eq(new BigDecimal("-100.00")),eq("refund_reserve"),isNull(),any());assertEquals("paid",payment.get("status"));assertTrue(writes.stream().noneMatch(q->q.contains("UPDATE t_currency_payments")));}
 @Test void verifiedCnyFeeDifferenceReservesOnlyOriginalWalletCredit()throws Exception{var s=service();payment.put("payment_minor",new BigDecimal("10100"));verified.put("payment_minor",new BigDecimal("10100"));var result=s.reserve("buyer",input());assertEquals(new BigDecimal("10100"),result.get("payment_minor"));verify(money).addBalance(eq("buyer"),eq(new BigDecimal("-100.00")),eq("refund_reserve"),isNull(),any());}
 @Test void requestRetryDoesNotReserveTwice()throws Exception{var s=service();existing("requested");refund.put("request_id",REQUEST);byRequest=refund;s.reserve("buyer",input());verifyNoInteractions(money);assertTrue(writes.isEmpty());}
 @Test void reusedKeyCannotChangeRefundReason()throws Exception{var s=service();existing("requested");byRequest=refund;code("REFUND_REQUEST_REUSED",()->s.reserve("buyer",new Create(PAYMENT,REQUEST,"Different reason")));verifyNoInteractions(money);}
 @Test void unDispatchedCancellationAllowsNewAttemptWithoutOverwritingHistory()throws Exception{var s=service();s.reserve("buyer",input());String original=refund.get("id").toString();s.cancel(original,"buyer");var next=s.reserve("buyer",new Create(PAYMENT,"223e4567-e89b-42d3-a456-426614174000","Corrected reason"));assertNotEquals(original,next.get("id"));verify(money,times(2)).addBalance(eq("buyer"),eq(new BigDecimal("-100.00")),eq("refund_reserve"),isNull(),any());verify(money,times(1)).addBalance(eq("buyer"),eq(new BigDecimal("100.00")),eq("refund_release"),isNull(),any());verify(db,times(2)).queryForList(contains("payment_id=? AND active_slot=1 FOR UPDATE"),eq(PAYMENT));}
 @Test void approvalDoesNotDispatchOrDebitAgain()throws Exception{var s=service();existing("requested");assertEquals("approved",s.review(ID,"admin",new Review(true,"checked")).get("status"));verifyNoInteractions(money);assertTrue(writes.stream().noneMatch(q->q.contains("dispatched_at")));}
 @Test void rejectionReleasesReserveOnlyOnce()throws Exception{var s=service();existing("requested");s.review(ID,"admin",new Review(false,"not approved"));s.review(ID,"admin",new Review(false,"not approved"));verify(money,times(1)).addBalance(eq("buyer"),eq(new BigDecimal("100.00")),eq("refund_release"),isNull(),any());}
 @Test void ownerCancellationIsIdempotentAndApprovedRequestCannotCancel()throws Exception{var s=service();existing("requested");s.cancel(ID,"buyer");s.cancel(ID,"buyer");verify(money,times(1)).addBalance(any(),any(),eq("refund_release"),any(),any());existing("approved");code("REFUND_CANCEL_NOT_ALLOWED",()->s.cancel(ID,"buyer"));}
 @Test void dispatchClaimCannotBeAcquiredTwice()throws Exception{var s=service();existing("approved");assertEquals("dispatching",s.claim(ID,"admin").get("status"));code("REFUND_DISPATCH_NOT_ALLOWED",()->s.claim(ID,"admin"));verifyNoInteractions(money);}
 @Test void forgedAmountsCannotFinalizeRefund()throws Exception{var s=service();existing("dispatching");code("REFUND_RECEIPT_MISMATCH",()->s.receipt(ID,new Receipt(ID,PAYMENT,"tx","provider-refund","CNY",new BigInteger("10000"),new BigInteger("9999"),"succeeded")));assertTrue(writes.isEmpty());verifyNoInteractions(money);}
 @Test void processingNeverReleasesWalletReserve()throws Exception{var s=service();existing("dispatching");assertEquals("processing",s.receipt(ID,receipt("processing")).get("status"));verifyNoInteractions(money);}
 @Test void successfulRefundDoesNotCreditWalletAgainAndCanReplay()throws Exception{var s=service();existing("dispatching");s.receipt(ID,receipt("succeeded"));s.receipt(ID,receipt("succeeded"));verifyNoInteractions(money);assertEquals("paid",payment.get("status"));assertFalse((Boolean)refund.get("wallet_released"));}
 @Test void verifiedClosedRefundReturnsReserveOnce()throws Exception{var s=service();existing("dispatching");s.receipt(ID,receipt("closed"));s.receipt(ID,receipt("closed"));verify(money,times(1)).addBalance(eq("buyer"),eq(new BigDecimal("100.00")),eq("refund_release"),isNull(),any());}
 @Test void lateSuccessCannotOverrideReleasedClosedRefund()throws Exception{var s=service();existing("closed");refund.put("wallet_released",true);refund.put("provider_refund_id","provider-refund");code("REFUND_TERMINAL_CONFLICT",()->s.receipt(ID,receipt("succeeded")));verifyNoInteractions(money);}
 @Test void pendingSourceRowAndRefundAreLockedBeforeWallet()throws Exception{var s=service();s.reserve("buyer",input());var sequence=inOrder(db,money);sequence.verify(db).queryForList(startsWith("SELECT * FROM t_currency_payments WHERE id=? AND user_id=? FOR UPDATE"),eq(PAYMENT),eq("buyer"));sequence.verify(db).queryForList(startsWith("SELECT * FROM t_payment_refunds WHERE user_id"),eq("buyer"),eq(REQUEST));sequence.verify(money).lockBalance("buyer");}
}
